package com.ruoyi.hexu;
import java.util.*;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.BusinessException.require;
/** Tenant-scoped staff assignments and read-only, redacted audit access. */
public final class HexuOperations {
 private final HexuStore db;public HexuOperations(HexuStore d){db=d;}
 private void owner(Actor a,long shop){db.manage(a,shop,"OWNER");}
 public List<Map<String,Object>> staff(Actor a,long shop){owner(a,shop);return db.jdbc().queryForList("select s.user_id,s.role_code,u.user_name,u.nick_name,u.status from hx_staff s join sys_user u on u.user_id=s.user_id where s.shop_id=? order by s.user_id",shop);}
 public Map<String,Object> lookup(Actor a,long shop,String login){owner(a,shop);require(login.matches("[A-Za-z0-9_.@-]{2,64}"),"请填写完整后台登录账号");return db.one("select user_id,user_name,nick_name,status from sys_user where user_name=? and del_flag='0'",login);}
 public Map<String,Object> assign(Actor a,long shop,Map<String,Object>b){owner(a,shop);long user=number(b,"userId");require(user>1,"平台管理员不能通过商城岗位修改");require(!a.staff||a.id!=user,"不能修改本人岗位，请由商城拥有者或平台复核");Map<String,Object>u=db.one("select user_id,user_name,status from sys_user where user_id=? and del_flag='0' for update",user);String role=str(b,"role");require(Arrays.asList("OWNER","CATALOG","ORDER","FINANCE","WAREHOUSE","SUPPORT","OPERATOR").contains(role),"岗位无效");require(!bool(b,"enabled")||"0".equals(str(u,"status")),"后台账号已停用，请由平台先启用账号");require(str(b,"reason").trim().length()>=2&&str(b,"reason").length()<=500,"请填写岗位变更原因");Map<String,Object>before=db.optional("select * from hx_staff where shop_id=? and user_id=?",shop,user);if(!bool(b,"enabled"))db.jdbc().update("delete from hx_staff where shop_id=? and user_id=?",shop,user);else if(before==null)db.jdbc().update("insert into hx_staff(user_id,shop_id,role_code) values(?,?,?)",user,shop,role);else db.jdbc().update("update hx_staff set role_code=? where shop_id=? and user_id=?",role,shop,user);Map<String,Object>after=map("userId",user,"userName",u.get("user_name"),"role",role,"enabled",bool(b,"enabled"),"reason",str(b,"reason"));db.audit(a,shop,"STAFF_ASSIGN",String.valueOf(user),before,after);return after;}
 public List<Map<String,Object>> audit(Actor a,long shop){owner(a,shop);List<Map<String,Object>>rows=db.jdbc().queryForList("select id,shop_id,actor_id,actor_kind,source,request_id,ip_masked,action,reference_id,created_at from hx_audit where shop_id=? order by id desc limit 500",shop);for(Map<String,Object>r:rows)r.put("actorName",actorName(r));return rows;}
 private String actorName(Map<String,Object>r){if("MEMBER".equals(str(r,"actor_kind"))){Map<String,Object>m=db.optional("select name from hx_member where id=?",r.get("actor_id"));return m==null?"会员 "+r.get("actor_id"):str(m,"name");}return "SYSTEM".equals(str(r,"actor_kind"))?"系统任务":("STAFF".equals(str(r,"actor_kind"))?"后台账号 ":"历史账号 ")+r.get("actor_id");}
 public Map<String,Object> auditDetail(Actor a,long shop,long id){owner(a,shop);Map<String,Object>r=db.one("select * from hx_audit where shop_id=? and id=?",shop,id);r.put("actorName",actorName(r));for(String key:Arrays.asList("before_json","after_json")){Object raw=r.remove(key);Object parsed=null;try{parsed=raw==null?null:new com.fasterxml.jackson.databind.ObjectMapper().readValue(raw.toString(),Object.class);}catch(Exception e){parsed="历史数据格式无法解析";}r.put(key.substring(0,key.indexOf('_')),redact(parsed));}return r;}
 private Object redact(Object v){if(v instanceof Map){Map<String,Object>r=new LinkedHashMap<>();for(Map.Entry<?,?>e:((Map<?,?>)v).entrySet()){String k=e.getKey().toString(),lower=k.toLowerCase(Locale.ROOT);if(k.startsWith("_secure_")||lower.contains("secret")||lower.contains("password")||lower.contains("token")||Arrays.asList("cipher_bytes","iv").contains(lower))continue;Object value=e.getValue();if(Arrays.asList("accountnumber","bank","idcard","identitynumber","phone","身份证号","银行卡号","手机号码").contains(lower)&&value!=null){String text=value.toString();value=text.isEmpty()?"":"****"+text.substring(Math.max(0,text.length()-4));}else {if(lower.endsWith("_json")&&value instanceof String)try{value=new com.fasterxml.jackson.databind.ObjectMapper().readValue((String)value,Object.class);}catch(Exception ignored){}value=redact(value);}r.put(k,value);}return r;}if(v instanceof List){List<Object>r=new ArrayList<>();for(Object x:(List<?>)v)r.add(redact(x));return r;}return v;}
}
